p11_typen.FB_Messung:
FUNCTION_BLOCK "FB_Messung"
VAR_INPUT
   Rohwert : Int;       // Analogwert 0…27648
   Temperatur : Real;   // °C
   Freigabe : Bool;
   Laufzeit : Time;     // seit dem Einschalten
END_VAR
VAR_OUTPUT
   Anzeige : Real;
   Warnung : Bool;
END_VAR
BEGIN
   IF #Freigabe AND #Laufzeit >= T#2S THEN
      #Anzeige := #Temperatur + INT_TO_REAL(#Rohwert) / 1000.0;
   ELSE
      #Anzeige := 0.0;
   END_IF;
   #Warnung := #Anzeige > 80.0;
END_FUNCTION_BLOCK

p11_konstante.FB_Palette:
FUNCTION_BLOCK "FB_Palette"
VAR_INPUT
   Teil : Bool;         // Teil wird abgelegt
   Quittieren : Bool;   // volle Palette getauscht
END_VAR
VAR_OUTPUT
   Voll : Bool;
   Frei : Int;          // freie Plätze
   Anzahl : Int;
END_VAR
VAR
   Merker : Bool;
END_VAR
VAR CONSTANT
   MAX_TEILE : Int := 20;   // Plätze pro Palette
END_VAR
BEGIN
   IF #Teil AND NOT #Merker THEN
      IF #Anzahl < #MAX_TEILE THEN
         #Anzahl := #Anzahl + 1;
      END_IF;
   END_IF;
   #Merker := #Teil;
   #Voll := #Anzahl >= #MAX_TEILE;
   #Frei := #MAX_TEILE - #Anzahl;
   IF #Quittieren AND #Voll THEN
      #Anzahl := 0;
   END_IF;
END_FUNCTION_BLOCK

p11_arraygrenzen.FB_Mittelwert:
FUNCTION_BLOCK "FB_Mittelwert"
VAR_INPUT
   Werte : Array[1..10] of Real;   // Messpunkte 1…10
END_VAR
VAR_OUTPUT
   Mittel : Real;
END_VAR
VAR_TEMP
   i : Int;
   Summe : Real;
END_VAR
BEGIN
   #Summe := 0.0;
   FOR #i := 1 TO 10 DO
      #Summe := #Summe + #Werte[#i];
   END_FOR;
   #Mittel := #Summe / 10.0;
END_FUNCTION_BLOCK

