p11_bits.FB_Antriebsstatus:
FUNCTION_BLOCK "FB_Antriebsstatus"
VAR_INPUT
   Status : Word;       // Statuswort des Umrichters
   Quittieren : Bool;
END_VAR
VAR_OUTPUT
   Bereit : Bool;       // Bit 0
   Stoerung : Bool;     // Bit 3
   Warnung : Bool;      // Bit 5
   Fehlerbits : Word;   // nur Bit 3 und Bit 5 (Maske 16#0028)
   Befehl : Word;       // Steuerwort an den Umrichter
END_VAR
BEGIN
   #Bereit := #Status.%X0;
   #Stoerung := #Status.%X3;
   #Warnung := #Status.%X5;
   #Fehlerbits := #Status AND 16#0028;
   #Befehl := 16#0000;
   #Befehl.%X7 := #Quittieren;
END_FUNCTION_BLOCK

