p11_boss.FB_Zelle:
FUNCTION_BLOCK "FB_Zelle"
VAR_INPUT
   Start : Bool;
   Stopp : Bool;
   Teil_da : Bool;
   Quittieren : Bool;
END_VAR
VAR_OUTPUT
   Band : Bool;
   Lampe_Gruen : Bool;
   Lampe_Rot : Bool;
   Anzahl : DInt;          // Tagesproduktion
END_VAR
VAR
   Betrieb : Bool;
   Stoerung : Bool;
   Teil_alt : Bool;
   Ueberwachung : TON;     // Transportzeit
END_VAR
VAR_TEMP
   Flanke : Bool;
END_VAR
VAR CONSTANT
   MAX_TRANSPORT : Time := T#5S;
END_VAR
BEGIN
   // Betrieb mit Selbsthaltung — Störung schaltet ab
   #Betrieb := (#Start OR #Betrieb) AND NOT #Stopp AND NOT #Stoerung;
   #Band := #Betrieb AND NOT #Teil_da;

   // Transportüberwachung: das Teil muss innerhalb MAX_TRANSPORT ankommen
   #Ueberwachung(IN := #Band, PT := #MAX_TRANSPORT);
   IF #Ueberwachung.Q THEN
      #Stoerung := TRUE;
   END_IF;
   IF #Quittieren THEN
      #Stoerung := FALSE;
   END_IF;

   // Teile zählen (steigende Flanke)
   #Flanke := #Teil_da AND NOT #Teil_alt;
   #Teil_alt := #Teil_da;
   IF #Flanke THEN
      #Anzahl := #Anzahl + 1;
   END_IF;

