   Min : Real;      // Alarmgrenze unten
   Max : Real;      // Alarmgrenze oben
END_VAR
VAR_OUTPUT
   Status : Int;    // 0 OK, 1 Drahtbruch, 2 Überlauf
   Alarm : Bool;
END_VAR
VAR_TEMP
