END_VAR
BEGIN
   IF #Roh < 0 THEN
      #Status := 1;
      #Alarm := TRUE;
      #FC_Messwert := #UG;
   ELSIF #Roh > 27648 THEN
      #Status := 2;
      #Alarm := TRUE;
      #FC_Messwert := #UG;
   ELSE
      #Wert := #UG + (#OG - #UG) * INT_TO_REAL(#Roh) / 27648.0;
      #Status := 0;
      #Alarm := #Wert < #Min OR #Wert > #Max;
      #FC_Messwert := #Wert;
   END_IF;
END_FUNCTION

