      ELSE
         #Charge.Protokoll[#i] := '';
      END_IF;
   END_FOR;
   IF #Charge.Anzahl > 0 THEN
      #Charge.Mittel := #Summe / INT_TO_REAL(#Charge.Anzahl);
   ELSE
      #Charge.Mittel := 0.0;
   END_IF;
   #Charge.Zusammenfassung := CONCAT(IN1 := 'OK ', IN2 := INT_TO_STRING(#Charge.OK_Anzahl), IN3 := '/', IN4 := INT_TO_STRING(#Charge.Anzahl));
