p15_schrittkette.FB_Pick:
FUNCTION_BLOCK "FB_Pick"
VAR_INPUT
   Start : Bool;        // Freigabe (Automatik)
   Teil_da : Bool;      // Teil liegt an der Greifstation
   Greifer_zu : Bool;   // Rückmeldung: Greifer geschlossen
   Gut : Bool;          // Teil in Ordnung → LAGER (+90°), sonst NACHARBEIT (−90°)
END_VAR
VAR_OUTPUT
   Arm : Int;           // Soll-Winkel
   Greifer_Auf : Bool;
   Schritt : Int;
   Fertig : Bool;       // TRUE für einen Zyklus, wenn ein Teil abgelegt ist
END_VAR
VAR
   Ziel : Int;          // Zielwinkel für das aktuelle Teil
   T_Schwenk : TON;
   T_Ablegen : TON;
   T_Zurueck : TON;
END_VAR
BEGIN
   #T_Schwenk(IN := #Schritt = 2, PT := T#1S);
   #T_Ablegen(IN := #Schritt = 3, PT := T#500MS);
   #T_Zurueck(IN := #Schritt = 4, PT := T#1S);
   #Fertig := FALSE;
   CASE #Schritt OF
      0: // Warten auf Teil
         IF #Start AND #Teil_da THEN
            IF #Gut THEN
               #Ziel := 90;
            ELSE
               #Ziel := -90;
            END_IF;
            #Schritt := 1;
         END_IF;
      1: // Greifen
         IF #Greifer_zu THEN
            #Schritt := 2;
         END_IF;
      2: // Schwenken
         IF #T_Schwenk.Q THEN
            #Schritt := 3;
         END_IF;
      3: // Ablegen
         IF #T_Ablegen.Q THEN
            #Schritt := 4;
         END_IF;
      4: // Zurück in Grundstellung
         IF #T_Zurueck.Q THEN
            #Schritt := 0;
            #Fertig := TRUE;
         END_IF;
   END_CASE;
   #Greifer_Auf := NOT (#Schritt = 1 OR #Schritt = 2);
   IF #Schritt = 2 OR #Schritt = 3 THEN
      #Arm := #Ziel;
   ELSE
      #Arm := 0;
   END_IF;
END_FUNCTION_BLOCK

p15_global_dbg.FB_Zaehler:
FUNCTION_BLOCK "FB_Zaehler"
VAR_INPUT
   Sensor : Bool;
END_VAR
VAR_OUTPUT
   Anzahl : Int;
END_VAR
VAR
   Alt : Bool;
END_VAR
BEGIN
   IF #Sensor AND NOT #Alt THEN
      #Anzahl := #Anzahl + 1;
   END_IF;
   #Alt := #Sensor;
END_FUNCTION_BLOCK

p15_export.FB_Signalsaeule:
// Signalsäule nach Firmenstandard
// Rot blinkt bei Störung (0,5 s), Gelb = Warnung oder Wartung, Grün = Betrieb ohne Störung
FUNCTION_BLOCK "FB_Signalsaeule"
VAR_INPUT
   Betrieb : Bool;
   Stoerung : Bool;
   Warnung : Bool;
   Wartung : Bool;     // Wartung fällig
END_VAR
VAR_OUTPUT
   Rot : Bool;
   Gelb : Bool;
   Gruen : Bool;
END_VAR
VAR
   Blink : TON;        // Blinktakt
   Takt : Bool;
END_VAR
BEGIN
   #Blink(IN := NOT #Blink.Q, PT := T#500MS);
   IF #Blink.Q THEN
      #Takt := NOT #Takt;
   END_IF;
   #Rot := #Stoerung AND #Takt;
   #Gelb := #Warnung OR #Wartung;
   #Gruen := #Betrieb AND NOT #Stoerung;
END_FUNCTION_BLOCK

p15_final.FB_Zelle:
FUNCTION_BLOCK "FB_Zelle"
VAR_INPUT
   Start : Bool;
   Stopp : Bool;
   Quittieren : Bool;
   Teil_da : Bool;       // Lichtschranke Greifstation
   RM_Band : Bool;       // Rückmeldung Bandmotor
   Greifer_zu : Bool;    // Rückmeldung Greifer
   Teil_Nr : DInt;       // vom Scanner
   Gewicht : Real;       // von der Waage
END_VAR
VAR_OUTPUT
   Band : Bool;
   Arm : Int;
   Greifer_Auf : Bool;
   Stoerung : Bool;
   Anzahl_OK : Int;
   Anzahl_NOK : Int;
   Meldung : String[30];
END_VAR
VAR
   Betrieb : Bool;
   Motor : "FB_Motor_Std";
   Pick : "FB_Pick";
END_VAR
BEGIN
   // Betrieb: Start/Stopp mit Selbsthaltung, Störung schaltet ab
   #Betrieb := (#Start OR #Betrieb) AND NOT #Stopp AND NOT #Stoerung;

   // Band läuft, solange kein Teil da ist und der Greifer in Grundstellung wartet
   #Motor(Start := #Betrieb AND NOT #Teil_da AND #Pick.Schritt = 0,
          Stopp := NOT #Betrieb OR #Teil_da OR #Pick.Schritt <> 0,
          Rueckmeldung := #RM_Band, Quittieren := #Quittieren,
          Lauf => #Band, Stoerung => #Stoerung);

   // Greifzyklus: gute Teile ins LAGER, schlechte in die NACHARBEIT
   #Pick(Start := #Betrieb, Teil_da := #Teil_da, Greifer_zu := #Greifer_zu,
         Gut := #Gewicht >= 480.0 AND #Gewicht <= 520.0,
         Arm => #Arm, Greifer_Auf => #Greifer_Auf);

   // Statistik und Meldung, sobald ein Teil abgelegt ist
   IF #Pick.Fertig THEN
      IF #Pick.Ziel > 0 THEN
         #Anzahl_OK := #Anzahl_OK + 1;
      ELSE
         #Anzahl_NOK := #Anzahl_NOK + 1;
      END_IF;
      #Meldung := "FC_Teiletext"(Nr := #Teil_Nr, Gewicht := REAL_TO_INT(#Gewicht), OK := #Pick.Ziel > 0);
   END_IF;
   IF #Stoerung THEN
      #Meldung := 'Störung Band';
   ELSIF NOT #Betrieb THEN
      #Meldung := 'Bereit';
   ELSIF #Meldung = 'Bereit' OR #Meldung = '' THEN
      #Meldung := 'Automatik läuft';
   END_IF;
END_FUNCTION_BLOCK
